package com.ribeira.donation.application;

import com.ribeira.inventory.domain.InventoryEnums.ExpirationStatus;
import com.ribeira.shared.domain.UnitOfMeasure;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.util.List;
import java.util.UUID;

/**
 * DONATION_RECEIVE. Shared by REST and synchronization; every ID is generated by the client so
 * later offline operations can reference the batches before the server has seen them.
 */
public record ReceiveDonation(
    @NotNull UUID communityId,
    @NotNull UUID donationId,
    UUID donorId,
    @Size(max = 200) String originDescription,
    @NotNull Instant receivedAt,
    @Size(max = 1000) String notes,
    @NotEmpty @Size(max = 100) List<@Valid @NotNull Item> items) {

  public record Item(
      @NotNull UUID itemId,
      @NotNull UUID foodId,
      @NotNull @Positive BigDecimal quantity,
      @NotNull UnitOfMeasure unit,
      @Size(max = 500) String notes,
      @NotEmpty @Size(max = 50) List<@Valid @NotNull BatchSplit> batches) {}

  public record BatchSplit(
      @NotNull UUID batchId,
      @NotNull @Positive BigDecimal quantity,
      UUID storageLocationId,
      @NotNull ExpirationStatus expirationStatus,
      LocalDate expirationDate,
      @Size(max = 500) String notes) {}
}
